/bin/bash -lc "python - <<'PY'
import json, time
from bioblend.galaxy import GalaxyInstance
key=open('[REDACTED LOCAL PATH]').read().strip()
gi=GalaxyInstance('https://usegalaxy.org', key=key)
jobs=json.load(open('[REDACTED LOCAL PATH]'))
summary={}
for chrom,info in jobs.items():
    jid=info.get('jid'); outid=info.get('outid')
    if not jid:
        summary[chrom]=info; continue
    try:
        j=gi.jobs.wait_for_job(jid, maxwait=3600, interval=5)
        state=j['state']
    except Exception as e:
        state='ERROR:'+str(e)
    dstate=None; fsize=None
    if outid:
        try:
            d=gi.datasets.show_dataset(outid)
            dstate=d['state']; fsize=d['file_size']
        except Exception as e:
            dstate='ERR'; fsize=str(e)
    summary[chrom]={'state':state,'dstate':dstate,'file_size':fsize,'outid':outid,'jid':jid}
    print(chrom,summary[chrom],flush=True)
with open('[REDACTED LOCAL PATH]','w') as f: json.dump(summary,f,indent=2)
print('DONE')
PY"

